-- P0-1 MANUAL PREFLIGHT: read-only; run against a copy of the production dump.
SELECT VERSION() server_version,DATABASE() database_name;
SELECT u.username,u.user_id,u.employee_id,e.organizational_unit_id,ou.unit_code employee_unit FROM users u LEFT JOIN employees e ON e.employee_id=u.employee_id LEFT JOIN organizational_units ou ON ou.organizational_unit_id=e.organizational_unit_id WHERE u.username IN ('registrar','exam.board') ORDER BY u.username;
SELECT expected.username,COUNT(u.user_id) matches,COUNT(u.employee_id) linked_employee FROM (SELECT 'registrar' username UNION ALL SELECT 'exam.board') expected LEFT JOIN users u ON BINARY u.username=BINARY expected.username GROUP BY expected.username;
SELECT unit_type_id,type_code,type_name,is_active FROM organizational_unit_types WHERE type_code IN ('administration','center','club','college','directorate','institute','lab','office','presidency','unit','vice_presidency') ORDER BY type_code;
SELECT u.organizational_unit_id,u.unit_code,u.unit_name,t.type_code,p.unit_code parent_code,u.is_active FROM organizational_units u JOIN organizational_unit_types t ON t.unit_type_id=u.unit_type_id LEFT JOIN organizational_units p ON p.organizational_unit_id=u.parent_unit_id WHERE u.unit_code IN ('PRES','1','11','12','13','2','21','22','23','3','31','32','4','41','42','5','51','52','6','7','71','711','712','713','714','715','72','721','722','723','73','731','732','733','734','735','736','8','81','811','812','813','82','821','822','823','9','91','911','912','913','914','92','921','922','923','924','925','VP_ADMIN','REG_OFFICE','EXAM_OFFICE') ORDER BY u.unit_code;
SELECT table_name,column_name,constraint_name FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND referenced_table_name='organizational_units' AND referenced_column_name='organizational_unit_id' ORDER BY table_name,column_name;
SELECT IF((SELECT COUNT(*) FROM users WHERE BINARY username=BINARY 'registrar' AND employee_id IS NOT NULL)=1 AND (SELECT COUNT(*) FROM users WHERE BINARY username=BINARY 'exam.board' AND employee_id IS NOT NULL)=1 AND (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code IN ('administration','center','club','college','directorate','institute','lab','office','presidency','unit','vice_presidency') AND is_active=1)=11,1,0) can_apply,'required users, employee links, and existing unit types' gate;
